# -*- coding: utf-8 -*-
# Tur Q yamasi (24 Ekim 2026): -ta/-te bulunma eki, sozlukte olmayan ad + kesmeli -ya ayri, yabanci Latin harfleri,
# sozluk kayitlari (duzeltmeler.tsv), 4 kok (kok_elle.tsv), tests/test_tur_q.py.
# Kod klasorunde calistirilir. Tekrar calistirilabilir (yapilmissa ATLANDI); beklenen metin yoksa HATA ile durur.
import os, sys

def oku(p):
    return open(p, encoding="utf-8").read()

def yaz(p, s):
    open(p, "w", encoding="utf-8").write(s)

if not os.path.isfile("app/engine/transliterator.py"):
    print("HATA: kod klasorunde degilsiniz"); sys.exit(1)

p = "app/engine/transliterator.py"
s = oku(p)
for ad, eski, yeni in [
    ("kesmeli -ya", '            return rules.transliterate_word_with_suffix(base) + rules.ekleri_yaz(b, [], tails_l, harmony)\n',
     '            _yazi = rules.transliterate_word_with_suffix(base)\n            if tails_l in (["ya"], ["ye"]) and b.endswith(("i", "\u0131", "\xee")) and _yazi.endswith("\u06cc") and " " not in _yazi \\\n                    and turkish_lower(word).replace("\u2019", "\'").endswith(("\'ya", "\'ye")):\n                return _yazi + " \u06cc\u0647"   # Tur Q: sozlukte olmayan ad da (Tanri\'ya, Habesi\'ye) Tur J gibi ayri\n            return _yazi + rules.ekleri_yaz(b, [], tails_l, harmony)\n'),
    ("-ta/-te", '        osm = re.sub(r"(\u062a\u0627\u0646|\u062a\u0646)$", "\u062f\u0646", osm)\n',
     '        osm = re.sub(r"(\u062a\u0627\u0646|\u062a\u0646)$", "\u062f\u0646", osm)\n    # Tur Q: bulunma eki -ta/-te (ger\xe7ekte\u060c sonu\xe7ta\u060c sava\u015fta) \u062f\u0647; kelime s\xf6zl\xfckte tam kay\u0131tl\u0131ysa (hasta\u060c n\xfckte\u060c liste) dokunulmaz\n    if re.search(r"[p\xe7tks\u015fhf]t[ae]$", l) and osm.endswith("\u062a\u0647") and len(l) >= 4 \\\n            and not dictionary.lookup_exact(l) and (l[:-2] in dictionary._zkok() or dictionary.lookup_exact(l[:-2])) \\\n            and not (l[:-1] in dictionary._zkok() or dictionary.lookup_exact(l[:-1])):   # \xfcst+e (\xfcste) y\xf6nelme\n        osm = osm[:-2] + "\u062f\u0647"\n'),
]:
    if yeni in s:
        print("ATLANDI:", ad)
    elif s.count(eski) == 1:
        s = s.replace(eski, yeni); print("YAPILDI:", ad)
    else:
        print("HATA: beklenen metin bulunamadi:", ad); sys.exit(1)
if "_transliterate_text_yabancisiz" in s:
    print("ATLANDI: yabanci harf")
else:
    s = s + '\n\n# ---- Tur Q: Turkcede olmayan Latin harfleri (Fransizca/Almanca alinti: Levi, Traite, dass) duz harfe indirilir ----\n# (yoksa ciktida Latin harf kaliyordu). Turk harfleri (\xe2 \xee \xfb \xe7 \xf6 \xfc \u015f \u011f \u0131) ve ayin/kesme isaretleri dokunulmaz.\n_YABANCI_HARF = str.maketrans({\n    "\\u00e9": "e", "\\u00e8": "e", "\\u00ea": "e", "\\u00eb": "e", "\\u00c9": "E", "\\u00c8": "E", "\\u00ca": "E", "\\u00cb": "E",\n    "\\u00e0": "a", "\\u00e1": "a", "\\u00e4": "a", "\\u00e5": "a", "\\u00c0": "A", "\\u00c1": "A", "\\u00c4": "A", "\\u00c5": "A",\n    "\\u00f3": "o", "\\u00f2": "o", "\\u00f5": "o", "\\u00f8": "o", "\\u00d3": "O", "\\u00d2": "O", "\\u00d8": "O",\n    "\\u00ed": "i", "\\u00ec": "i", "\\u00ef": "i", "\\u00cd": "\\u0130", "\\u00cc": "\\u0130",   # OCR: Islam (I yerine I-akut) -> I noktali\n    "\\u00fa": "u", "\\u00f9": "u", "\\u00da": "U", "\\u00d9": "U",\n    "\\u00f1": "n", "\\u00d1": "N", "\\u0142": "l", "\\u0141": "L", "\\u013c": "l", "\\u013b": "L",\n    "\\u00df": "ss", "\\u0153": "oe", "\\u00e6": "ae",\n})\n_transliterate_text_yabancisiz = transliterate_text\n\n\ndef transliterate_text(turkish_text, *args, **kwargs):\n    if isinstance(turkish_text, str):\n        turkish_text = turkish_text.translate(_YABANCI_HARF)\n    return _transliterate_text_yabancisiz(turkish_text, *args, **kwargs)\n'
    print("YAPILDI: yabanci harf")
yaz(p, s)

